"""The in-app « pense-bête » : one page per section, shipped with the application and editable in place
by an administrator.

* the **default** pages come from ``appro/help/pense_bete.json``, generated by ``scripts/pense_bete.py``
  (the same source as ``docs/pense_bete_approvisionneur.html``) ;
* an administrator may **save** another text for a page (``app_help_pages``) : every user then sees that
  saved version, nothing else (no history, no mention of the earlier versions) ; deleting the row brings
  the default page back.
"""
from __future__ import annotations

import datetime as dt
import json
import re
from functools import lru_cache
from pathlib import Path
from typing import Any

from sqlalchemy import select
from sqlalchemy.orm import Session

from ..data.store import AppHelpPage, audit

DEFAULTS = Path(__file__).resolve().parents[1] / "help" / "pense_bete.json"
MAX_HTML = 400_000


@lru_cache(maxsize=1)
def default_pages() -> list[dict[str, Any]]:
    """The pages shipped with the application, in reading order (an empty list when the file is absent)."""
    if not DEFAULTS.exists():
        return []
    data = json.loads(DEFAULTS.read_text(encoding="utf-8"))
    return [p for p in data.get("pages", []) if p.get("slug") and p.get("html") is not None]


def _by_slug() -> dict[str, dict[str, Any]]:
    return {p["slug"]: p for p in default_pages()}


_SCRIPT = re.compile(r"<\s*(script|iframe|object|embed|style)\b[^>]*>.*?<\s*/\s*\1\s*>", re.I | re.S)
_LONE = re.compile(r"<\s*/?\s*(script|iframe|object|embed|style)\b[^>]*>", re.I)
_ON_ATTR = re.compile(r"\s+on[a-z]+\s*=\s*(\"[^\"]*\"|'[^']*'|[^\s>]+)", re.I)
_JS_URL = re.compile(r"(href|src)\s*=\s*([\"']?)\s*javascript:[^\"'>\s]*\2", re.I)


def sanitize(html: str) -> str:
    """Strip what an editor must never inject : scripts, frames, inline handlers, javascript: links."""
    out = _SCRIPT.sub("", html or "")
    out = _LONE.sub("", out)
    out = _ON_ATTR.sub("", out)
    out = _JS_URL.sub(r'\1=""', out)
    return out.strip()


def _row_out(p: dict[str, Any], row: AppHelpPage | None) -> dict[str, Any]:
    return {"slug": p["slug"], "part": p.get("part", ""), "part_title": p.get("part_title", ""),
            "title": row.title if row is not None and row.title else p.get("title", ""),
            "edited": row is not None, "updated_by": row.updated_by if row is not None else "",
            "updated_at": row.updated_at if row is not None else None}


def list_pages(session: Session) -> list[dict[str, Any]]:
    rows = {r.slug: r for r in session.scalars(select(AppHelpPage)).all()}
    return [_row_out(p, rows.get(p["slug"])) for p in default_pages()]


def get_page(session: Session, slug: str) -> dict[str, Any] | None:
    p = _by_slug().get(slug)
    if p is None:
        return None
    row = session.get(AppHelpPage, slug)
    return {**_row_out(p, row), "html": row.body_html if row is not None else p["html"]}


def save_page(session: Session, user: str, slug: str, html: str, title: str | None = None) -> dict[str, Any]:
    """Save the administrator's text for a page (creates or updates the row).  Does not commit."""
    p = _by_slug().get(slug)
    if p is None:
        raise KeyError(slug)
    clean = sanitize(html)
    if len(clean) > MAX_HTML:
        raise ValueError(f"page trop longue ({len(clean)} caractères, maximum {MAX_HTML})")
    row = session.get(AppHelpPage, slug)
    if row is None:
        row = AppHelpPage(slug=slug)
        session.add(row)
    row.body_html, row.updated_by, row.updated_at = clean, user, dt.datetime.now(dt.timezone.utc).replace(tzinfo=None)
    row.title = (title or "").strip()[:200] or row.title or ""
    audit(session, user, "save", "help_page", slug, None, {"title": row.title or p.get("title", ""), "chars": len(clean)})
    session.flush()
    return {**_row_out(p, row), "html": row.body_html}


def reset_page(session: Session, user: str, slug: str) -> dict[str, Any]:
    """Back to the text shipped with the application.  Does not commit."""
    p = _by_slug().get(slug)
    if p is None:
        raise KeyError(slug)
    row = session.get(AppHelpPage, slug)
    if row is not None:
        session.delete(row)
        audit(session, user, "reset", "help_page", slug, None, {})
        session.flush()
    return {**_row_out(p, None), "html": p["html"]}
